#include "timer_egtm.h"
#include "timer_egtm_private.h"

#define TIMER_EGTM_BIT_24_MAX 16777215
#define TIMER_EGTM_BIT_16_MAX 65535
#define TIMER_EGTM_MHZ_BASE 1000000
/**********************************************************************************************************************
 * API IMPLEMENTATION
 **********************************************************************************************************************/
/*
 * Get the TIMER_EGTM APP version.
 */
ACS_APP_VERSION_t TIMER_EGTM_GetAppVersion(void)
{
  ACS_APP_VERSION_t version;
  version.major = TIMER_EGTM_MAJOR_VERSION;
  version.minor = TIMER_EGTM_MINOR_VERSION;
  version.patch = TIMER_EGTM_PATCH_VERSION;

  return version;
}

/*
 * Initializes the TIMER_EGTM APP based on user configuration.
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_Init(TIMER_EGTM_t *handle)
{
  TIMER_EGTM_STATUS_t status = TIMER_EGTM_STATUS_SUCCESS;
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  if (!handle->app_is_initialized)
  {
    if (EGTM_GENERIC_Init(handle->egtm_generic_handle) == EGTM_GENERIC_STATUS_SUCCESS)
    {
      if (handle->timer_atom_handle != NULL_PTR)
      {
        TIMER_EGTM_Atom_Timer_init(handle->timer_atom_handle, handle->app_config->timer_atom_config);
        if (handle->app_config->time_interval_event == TRUE)
        {
          IfxEgtm_Atom_Ch_setNotification(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel, IfxEgtm_IrqMode_pulseNotify, TRUE, FALSE);
        }
        if (handle->app_config->single_shot_mode == TRUE)
        {
          IfxEgtm_Atom_Timer_setSingleMode(handle->timer_atom_handle, TRUE);
        }
        if (handle->app_config->start_after_init == TRUE)
        {
          TIMER_EGTM_Start(handle);
        }
      }
      else
      {
        TIMER_EGTM_Tom_Timer_init(handle->timer_tom_handle, handle->app_config->timer_tom_config);
        if (handle->app_config->time_interval_event == TRUE)
        {
          IfxEgtm_Tom_Ch_setNotification(handle->timer_tom_handle->tom, handle->timer_tom_handle->timerChannel, IfxEgtm_IrqMode_pulseNotify, TRUE, FALSE);
        }
        if (handle->app_config->single_shot_mode == TRUE)
        {
          IfxEgtm_Tom_Timer_setSingleMode(handle->timer_tom_handle, TRUE);
        }
        if (handle->app_config->start_after_init == TRUE)
        {
          TIMER_EGTM_Start(handle);
        }
      }
      handle->app_is_initialized = TRUE;
    }
    else
    {
      status = TIMER_EGTM_STATUS_FAILURE;
    }
  }

  return status;
}

/*
 * Starts the timer.
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_Start(TIMER_EGTM_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));
  if (handle->timer_atom_handle != NULL_PTR)
  {
    IfxEgtm_Atom_Timer_run(handle->timer_atom_handle);
  }
  else
  {
    IfxEgtm_Tom_Timer_run(handle->timer_tom_handle);
  }
  return TIMER_EGTM_STATUS_SUCCESS;
}

/*
 * Stops the timer.
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_Stop(TIMER_EGTM_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));
  if (handle->timer_atom_handle != NULL_PTR)
  {
    IfxEgtm_Atom_Timer_stop(handle->timer_atom_handle);
  }
  else
  {
    IfxEgtm_Tom_Timer_stop(handle->timer_tom_handle);
  }
  return TIMER_EGTM_STATUS_SUCCESS;
}

/*
 * Returns the current time in us.
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_GetTime(TIMER_EGTM_t *handle, float32 *time_interval)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  if (handle->timer_atom_handle != NULL_PTR)
  {
    Ifx_EGTM_CLS_ATOM_CH *atomCh = IfxEgtm_Atom_Ch_getChannelPointer(handle->timer_atom_handle->atom, handle->app_config->timer_atom_config->timerChannel);
    *time_interval = (float32)(atomCh->CN0.U) / handle->timer_atom_handle->clockFreq * TIMER_EGTM_MHZ_BASE;
  }
  else
  {
    Ifx_EGTM_CLS_TOM_CH *tomCh = IfxEgtm_Tom_Ch_getChannelPointer(handle->timer_tom_handle->tom, handle->app_config->timer_tom_config->timerChannel);
    *time_interval = (float32)(tomCh->CN0.U) / handle->timer_tom_handle->clockFreq * TIMER_EGTM_MHZ_BASE;
  }
  return TIMER_EGTM_STATUS_SUCCESS;
}

/*
 * Reset and clear the timer register.
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_Reset(TIMER_EGTM_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  if (handle->timer_atom_handle != NULL_PTR)
  {
    IfxEgtm_Atom_Agc_resetChannels(handle->timer_atom_handle->agc, handle->app_config->timer_atom_config->timerChannel);
    IfxEgtm_Atom_Ch_setCounterValue(handle->timer_atom_handle->atom, handle->app_config->timer_atom_config->timerChannel, 0);
  }
  else
  {
    IfxEgtm_Tom_Tgc_resetChannels(handle->timer_tom_handle->tgc[0], handle->app_config->timer_tom_config->timerChannel);
    IfxEgtm_Tom_Tgc_resetChannels(handle->timer_tom_handle->tgc[1], handle->app_config->timer_tom_config->timerChannel);
    IfxEgtm_Tom_Ch_setCounterValue(handle->timer_tom_handle->tom, handle->app_config->timer_tom_config->timerChannel, 0);
  }
  return TIMER_EGTM_STATUS_SUCCESS;
}

/*
 * Set the new time interval for the event generation in us.
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_SetTimeInterval(TIMER_EGTM_t *handle, float32 time_interval)
{
  TIMER_EGTM_STATUS_t status = TIMER_EGTM_STATUS_FAILURE;
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  float32 min = 0;
  float32 max = 0;

  if (handle->timer_atom_handle != NULL_PTR)
  {
    min = TIMER_EGTM_MHZ_BASE / handle->timer_atom_handle->clockFreq;
    max = TIMER_EGTM_MHZ_BASE / handle->timer_atom_handle->clockFreq * TIMER_EGTM_BIT_24_MAX;
    if (min <= time_interval && time_interval <= max)
    {
      handle->app_config->timer_atom_config->frequency = (float)(TIMER_EGTM_MHZ_BASE / time_interval);
      if (IfxEgtm_Atom_Timer_setFrequency(handle->timer_atom_handle, handle->app_config->timer_atom_config->frequency))
      {
        handle->timer_atom_handle->offset = IfxStdIf_Timer_sToTick(handle->timer_atom_handle->clockFreq,
                                                                   1.0f /
                                                                   handle->app_config->timer_atom_config->frequency *
                                                                   handle->app_config->timer_atom_config->startOffset);
        IfxEgtm_Atom_Ch_setCounterValue(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel, handle->timer_atom_handle->offset);
        IfxEgtm_Atom_Agc_setChannelsForceUpdate(handle->timer_atom_handle->agc, handle->timer_atom_handle->channelsMask, 0, 0, 0);
        IfxEgtm_Atom_Agc_trigger(handle->timer_atom_handle->agc);
        IfxEgtm_Atom_Agc_setChannelsForceUpdate(handle->timer_atom_handle->agc, 0, handle->timer_atom_handle->channelsMask, 0, 0);
        status = TIMER_EGTM_STATUS_SUCCESS;
      }
    }
  }
  else
  {
    min = TIMER_EGTM_MHZ_BASE / handle->timer_tom_handle->clockFreq;
    max = TIMER_EGTM_MHZ_BASE / handle->timer_tom_handle->clockFreq * TIMER_EGTM_BIT_16_MAX;
    if (min <= time_interval && time_interval <= max)
    {
      handle->app_config->timer_tom_config->frequency = (float)(TIMER_EGTM_MHZ_BASE / time_interval);
      if (IfxEgtm_Tom_Timer_setFrequency(handle->timer_tom_handle, handle->app_config->timer_tom_config->frequency))
      {
        handle->timer_tom_handle->offset = IfxStdIf_Timer_sToTick(handle->timer_tom_handle->clockFreq,
                                                                  1.0f /
                                                                  handle->app_config->timer_tom_config->frequency *
                                                                  handle->app_config->timer_tom_config->startOffset);
        IfxEgtm_Tom_Ch_setCounterValue(handle->timer_tom_handle->tom, handle->timer_tom_handle->timerChannel, handle->timer_tom_handle->offset);
        IfxEgtm_Tom_Tgc_setChannelsForceUpdate(handle->timer_tom_handle->tgc[0], handle->timer_tom_handle->channelsMask[0], 0, 0, 0);
        IfxEgtm_Tom_Tgc_trigger(handle->timer_tom_handle->tgc[0]);
        IfxEgtm_Tom_Tgc_setChannelsForceUpdate(handle->timer_tom_handle->tgc[0], 0, handle->timer_tom_handle->channelsMask[0], 0, 0);
        status = TIMER_EGTM_STATUS_SUCCESS;
      }
    }
  }
  return status;
}

/*
 * Get current time interval for the event generation in us.
 */
TIMER_EGTM_STATUS_t TIMER_EGTM_GetTimeInterval(TIMER_EGTM_t *handle, float32 *time_interval)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL && timer_interval != NULL));

  /* Get current timer interval */
  if (handle->timer_atom_handle != NULL_PTR)
  {
    *time_interval = (float32)TIMER_EGTM_MHZ_BASE / handle->app_config->timer_atom_config->frequency;
  }
  else
  {
    *time_interval = (float32)TIMER_EGTM_MHZ_BASE / handle->app_config->timer_tom_config->frequency;
  }
  return TIMER_EGTM_STATUS_SUCCESS;
}

/*
 * Indicates the occurrence of time interval event.
 */
boolean TIMER_EGTM_GetEvent(TIMER_EGTM_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));
  boolean status;
  if (handle->timer_atom_handle != NULL_PTR)
  {
    status = IfxEgtm_Atom_Ch_isZeroNotification(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel);
    status |= IfxEgtm_Atom_Ch_isOneNotification(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel);
  }
  else
  {
    status = IfxEgtm_Tom_Ch_isZeroNotification(handle->timer_tom_handle->tom, handle->app_config->timer_tom_config->timerChannel);
    status |= IfxEgtm_Tom_Ch_isOneNotification(handle->timer_tom_handle->tom, handle->app_config->timer_tom_config->timerChannel);
  }
  return status;
}

/*
 * Clears the period match interrupt status of the given timer.
 */
void TIMER_EGTM_ClearEvent(TIMER_EGTM_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));
  boolean status;
  if (handle->timer_atom_handle != NULL_PTR)
  {
    status = IfxEgtm_Atom_Ch_isZeroNotification(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel);
    if (status)
    {
      IfxEgtm_Atom_Ch_clearZeroNotification(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel);
    }
    status = IfxEgtm_Atom_Ch_isOneNotification(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel);
    if (status)
    {
      IfxEgtm_Atom_Ch_clearOneNotification(handle->timer_atom_handle->atom, handle->timer_atom_handle->timerChannel);
    }
  }
  else
  {
    status = IfxEgtm_Tom_Ch_isZeroNotification(handle->timer_tom_handle->tom, handle->timer_tom_handle->timerChannel);
    if (status)
    {
      IfxEgtm_Tom_Ch_clearZeroNotification(handle->timer_tom_handle->tom, handle->timer_tom_handle->timerChannel);
    }
    status = IfxEgtm_Tom_Ch_isOneNotification(handle->timer_tom_handle->tom, handle->timer_tom_handle->timerChannel);
    if (status)
    {
      IfxEgtm_Tom_Ch_clearOneNotification(handle->timer_tom_handle->tom, handle->timer_tom_handle->timerChannel);
    }
  }
}

